export type TranslationKey = keyof typeof translations.en;
export type InterpolationValues = Record<string, string | number>;
export type Translator = (key: TranslationKey, values?: InterpolationValues) => string;
export const translationParity: Record<TranslationKey, string> = translations.my;

export function translate(locale: Locale, key: TranslationKey, values?: InterpolationValues): string {
  const catalog: Record<TranslationKey, string> = translations[locale];
  const template = catalog[key];
  return values
    ? template.replace(/\{(\w+)\}/g, (_, name: string) => String(values[name] ?? `{${name}}`))
    : template;
}

interface I18nContextValue {
  locale: Locale;
  setLocale: (locale: Locale) => void;
  t: Translator;
  displayName: (item: Parameters<typeof displayCatalogName>[0], locale?: Locale) => string;
}

const I18nContext = createContext<I18nContextValue | undefined>(undefined);

function getStorage(): Storage | undefined {
  return typeof window === 'undefined' ? undefined : window.localStorage;
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [locale, setLocale] = useState<Locale>(() => readStoredLocale(getStorage()));

  useEffect(() => {
    document.documentElement.lang = locale;
    persistLocale(locale, getStorage());
  }, [locale]);

  const value = useMemo<I18nContextValue>(() => ({
    locale,
    setLocale,
    t: (key, values) => translate(locale, key, values),
    displayName: (item, itemLocale = locale) => displayCatalogName(item, itemLocale),
  }), [locale]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useI18n(): I18nContextValue {
  const context = useContext(I18nContext);
  if (!context) throw new Error('useI18n must be used within an I18nProvider');
  return context;
}

export { DEFAULT_LOCALE, LOCALE_STORAGE_KEY, normalizeLocale, readStoredLocale, persistLocale } from './localization';
export type { Locale } from './localization';
